int data[] = {1, 2, 3, 4, 5};
CHECK_EQ(sum(data, 5), 15);
CHECK_EQ(sum(data, 0), 0);
CHECK_EQ(sum(data, 1), 1);
CHECK_EQ(sum(data + 2, 3), 12);

solution:
int sum(const int* first, int count) {
    int total = 0;
    for (int i = 0; i < count; ++i) {
        total += first[i];
    }
    return total;
}
